"""Independently reconcile raw source-matched diagnostic counterfactuals, excluding timings."""
from __future__ import annotations

import argparse
from collections import Counter
import hashlib
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
MASKS = {'fanout': ['measurement', 'reading'], 'shared-tail': ['l0', 'l1']}
NAMES = {'fanout': ['patient', 'measurement', 'reading', 'diagnosis', 'severity', 'drug', 'route',
    'language', 'procedure', 'author', 'department', 'status'], 'shared-tail': ['s', 'a', 'l0', 'l1', 'r0', 'r1']}
RESULTS = {'fanout': (1_152_000, '3123987218479850048'), 'shared-tail': (1_048_576, '8327963502356915200')}


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def read_run(suite, fixture):
    folder = HERE / 'suites' / suite
    protocol = json.loads((folder / 'protocol.json').read_text())
    run = folder / 'runs' / fixture
    command = json.loads((run / 'command.json').read_text())
    process = json.loads((run / 'process-result.json').read_text())
    samples = [json.loads(line) for line in (run / 'samples.jsonl').read_text().splitlines()]
    metadata, rows = samples[0], samples[1:]
    expected_rows, checksum = RESULTS[fixture]
    checks = {
        'processSucceeded': process['exitCode'] == 0,
        'protocolPinned': command['protocolSha256'] == sha(folder / 'protocol.json'),
        'runtimePinned': protocol['runtimeSha256'] == command['runtimeSha256'] == sha(Path(protocol['runtime'])),
        'fourQueries': len(rows) == 4,
        'names': metadata['projectedNames'] == NAMES[fixture],
        'java': metadata['javaVersion'] == '25.0.5+8-LTS' and metadata['javaVendor'] == 'Eclipse Adoptium'
            and metadata['maxHeapBytes'] == 1_073_741_824,
        'queryBudget': metadata['perQueryLedgerLimitBytes'] == protocol['queryLimitBytes'],
        'globalBudget': metadata['globalLedgerLimitBytes'] == 1_073_741_824,
    }
    queries = []
    for index, row in enumerate(rows, 1):
        owner_path = run / 'page-records' / f'owner-{index}.jsonl'
        owner = [json.loads(line) for line in owner_path.read_text().splitlines()]
        header = owner[0]
        target_list = [record for record in owner if record['type'] == 'target']
        targets = {record['name']: record for record in target_list}
        pages = [record for record in owner if record['type'] == 'page']
        assert len(target_list) == len(targets)
        q = {
            'sourceIdentity': metadata['source'], 'stage': row['stage'], 'iteration': row['iteration'],
            'owner': header['owner'], 'rawOwnerFile': str(owner_path), 'rawOwnerSha256': sha(owner_path),
            'ledgerPeakBytes': row['ledgerPeakBytes'], 'lazyValueCalls': row['counters']['lazyValueCalls'],
            'ordinaryHits': sum(t['ordinaryHit'] for t in target_list),
            'factorHits': sum(t['factorHit'] for t in target_list),
            'publicationCalls': sum(t['publicationCall'] for t in target_list),
            'publicationSkipped': sum(t['publicationSkipped'] for t in target_list),
            'publicationWrites': sum(t['publicationWrite'] for t in target_list),
            'coordinateAttempts': sum(t['coordinateAttempt'] for t in target_list),
            'coordinateSuccesses': sum(t['coordinateSuccess'] for t in target_list),
            'pageAdmissions': sum(t['pageAdmitted'] for t in target_list),
            'pageRefusals': sum(t['pageRefused'] for t in target_list),
            'pageBytesGranted': sum(t['pageBytesGranted'] for t in target_list),
            'pageBytesReleased': sum(t['pageBytesReleased'] for t in target_list),
            'pageBytesAtClose': sum(p['claim'] for p in pages),
            'weakMisses': sum(t['ordinaryWeakMiss'] + t['factorWeakMiss'] for t in target_list),
            'witnessMisses': sum(t['ordinaryWitnessMiss'] + t['factorWitnessMiss'] for t in target_list),
            'selectedRoute': row['successfulSelections'], 'targets': targets,
        }
        local = {
            'namesAndAliases': [t['name'] for t in target_list] == NAMES[fixture]
                and all(t['target'] == t['canonical'] == i for i, t in enumerate(target_list)),
            'result': row['valid'] and row['complete'] and row['rowCountValid'] and row['checksumValid']
                and row['rows'] == expected_rows and row['checksum'] == checksum,
            'exactSharedBag': fixture != 'shared-tail' or row['exactBagValid'] and row['partialMembershipValid'],
            'chronology': row['stage'] == ('warmup' if index < 4 else 'measurement') and row['iteration'] == index - 4,
            'ledgerEndpoints': row['ledgerBeforeBytes'] == row['ledgerAfterBytes'] == 0 and row['ledgerReleased'],
            'findReads': sum(t['find'] for t in target_list) == row['bindingReads'] == row['rows'] * len(NAMES[fixture]),
            'hitsAndResolverReads': q['ordinaryHits'] + q['factorHits'] + q['lazyValueCalls'] == row['bindingReads'],
            'rememberCalls': sum(t['rememberCall'] for t in target_list) == q['lazyValueCalls'],
            'noExtraWeakDereferences': header['extraWeakDereferences'] == 0,
            'pageCount': header['pageCount'] == len(pages),
            'allGrantedPageBytesReleased': q['pageBytesGranted'] == q['pageBytesReleased'],
            'pageReleaseCounts': all(t['pageAdmitted'] == t['pagesReleased'] for t in target_list),
            'normalAUTO': row['autoRequested'] and row['auto'] and bool(row['successfulSelections'])
                and all('forced' not in route['mode'] for route in row['successfulSelections']),
            'nativeIR': row['counters']['semanticNativeCompiles'] == row['counters']['irOpened'] == 1
                and row['counters']['irRows'] == expected_rows,
            'compiledObservedQuery': index < 4 or row['counters']['compiledBinds'] == 1
                and row['counters']['interpretedBinds'] == 0,
            'activeAdjacency': row['adjacency']['stateBefore'] == row['adjacency']['stateAfter'] == 'ACTIVE'
                and row['adjacency']['lookupHits'] > 0,
        }
        for name, target in targets.items():
            local[f'{name}:findPartition'] = target['find'] == sum(target[key] for key in (
                'ordinaryIdMiss', 'ordinaryHit', 'ordinaryWeakMiss', 'ordinaryWitnessMiss'))
            local[f'{name}:factorPartition'] = target['factorLookup'] == sum(target[key] for key in (
                'factorInitialMiss', 'factorPageMiss', 'factorCellMiss', 'factorWeakMiss', 'factorWitnessMiss', 'factorHit'))
            local[f'{name}:publicationPartition'] = target['publicationCall'] == sum(target[key] for key in (
                'publicationInitialMiss', 'publicationOwnerMiss', 'publicationPageMiss', 'publicationComplete', 'publicationSkipped'))
            local[f'{name}:admissionPartition'] = target['pageAttempt'] == target['pageAdmitted'] + target['pageRefused']
        assert all(local.values()), (suite, fixture, index, [k for k, v in local.items() if not v])
        q['checks'] = local
        queries.append(q)
    assert all(checks.values()), (suite, fixture, checks)
    return {'protocol': str(folder / 'protocol.json'), 'protocolSha256': sha(folder / 'protocol.json'),
        'runtime': protocol['runtime'], 'runtimeSha256': protocol['runtimeSha256'], 'mask': protocol['mask'],
        'queryLimitBytes': protocol['queryLimitBytes'], 'checks': checks, 'queries': queries}


def paired(original, candidate, fixture, mode):
    pairs = []
    for first, second in zip(original['queries'], candidate['queries']):
        selected = MASKS[fixture]
        q = {'owner': first['owner'], 'mode': mode,
            'resolverBefore': first['lazyValueCalls'], 'resolverAfter': second['lazyValueCalls'],
            'factorHitsBefore': first['factorHits'], 'factorHitsAfter': second['factorHits'],
            'ordinaryHitsBefore': first['ordinaryHits'], 'ordinaryHitsAfter': second['ordinaryHits'],
            'ledgerBefore': first['ledgerPeakBytes'], 'ledgerAfter': second['ledgerPeakBytes'],
            'pageBytesBefore': first['pageBytesAtClose'], 'pageBytesAfter': second['pageBytesAtClose'],
            'pageRefusalsBefore': first['pageRefusals'], 'pageRefusalsAfter': second['pageRefusals'],
            'publicationCallsBefore': first['publicationCalls'], 'publicationCallsAfter': second['publicationCalls'],
            'publicationSkippedAfter': second['publicationSkipped'],
            'coordinateAttemptsBefore': first['coordinateAttempts'], 'coordinateAttemptsAfter': second['coordinateAttempts']}
        checks = {'routeEqual': first['selectedRoute'] == second['selectedRoute'],
            'noWeakWitnessMisses': first['weakMisses'] == second['weakMisses'] == first['witnessMisses'] == second['witnessMisses'] == 0}
        if mode == 'publication-only512':
            checks.update({'resolverEqual': first['lazyValueCalls'] == second['lazyValueCalls'],
                'ordinaryHitsEqual': first['ordinaryHits'] == second['ordinaryHits'],
                'factorHitsEqual': first['factorHits'] == second['factorHits'],
                'noAdmissionRefusals': first['pageRefusals'] == second['pageRefusals'] == 0,
                'sameDiagnosticRuntime': original['runtimeSha256'] == candidate['runtimeSha256']})
        if mode in ('publication-only512', 'normal-budget256'):
            for name, target in second['targets'].items():
                if name in selected:
                    checks[f'{name}:allCallsSkipped'] = target['publicationCall'] == target['publicationSkipped'] > 0
                    checks[f'{name}:noPagesOrFactorHits'] = target['pageAdmitted'] == target['publicationComplete'] \
                        == target['publicationWrite'] == target['factorHit'] == 0
                else:
                    checks[f'{name}:noSkippedCalls'] = target['publicationSkipped'] == 0
        if mode in ('all-overlay-neutrality512', 'masked-budget-neutrality'):
            for key in ('lazyValueCalls', 'ordinaryHits', 'factorHits', 'publicationCalls', 'publicationSkipped',
                'publicationWrites', 'coordinateAttempts', 'coordinateSuccesses', 'pageAdmissions',
                'pageRefusals', 'pageBytesGranted', 'pageBytesReleased', 'pageBytesAtClose', 'ledgerPeakBytes'):
                checks[key + 'Equal'] = first[key] == second[key]
        assert all(checks.values()), (fixture, mode, first['owner'], checks)
        q['checks'] = checks
        pairs.append(q)
    return pairs


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path, default=HERE / 'publication-counterfactual-analysis.json')
    args = parser.parse_args()
    original = {fixture: read_run('original512', fixture) for fixture in MASKS}
    all512 = {fixture: read_run('overlay-all512', fixture) for fixture in MASKS}
    omitted512 = {'fanout': read_run('overlay-fanout-omit512', 'fanout'),
        'shared-tail': read_run('overlay-shared-omit512', 'shared-tail')}
    all256 = read_run('overlay-shared-all256', 'shared-tail')
    omitted256 = read_run('overlay-shared-omit256', 'shared-tail')
    comparisons = {fixture: {
        'originalVersusEmptyMask': paired(original[fixture], all512[fixture], fixture, 'all-overlay-neutrality512'),
        'emptyVersusSelectedMask512': paired(all512[fixture], omitted512[fixture], fixture, 'publication-only512')}
        for fixture in MASKS}
    comparisons['shared-tail']['emptyVersusSelectedMask256'] = paired(all256, omitted256, 'shared-tail', 'normal-budget256')
    comparisons['shared-tail']['masked512VersusMasked256'] = paired(omitted512['shared-tail'], omitted256,
        'shared-tail', 'masked-budget-neutrality')
    result = {'format': 1, 'valid': True, 'performanceInference': False, 'scriptSha256': sha(Path(__file__)),
        'masks': MASKS, 'runs': {'original512': original, 'overlayAll512': all512, 'overlayOmitted512': omitted512,
            'sharedAll256': all256, 'sharedOmitted256': omitted256}, 'comparisons': comparisons,
        'releaseCoverage': 'Page grants/releases are explicit; ordinary/directory/memo are close snapshots. '
            'Harness ledger endpoints are separately zero. No physical heap residency claim.'}
    with args.output.open('x') as stream:
        json.dump(result, stream, indent=2, sort_keys=True)
        stream.write('\n')
    print(json.dumps({'valid': True, 'performanceInference': False, 'output': str(args.output),
        'primary': {fixture: values['emptyVersusSelectedMask512'][-1] for fixture, values in comparisons.items()},
        'normalBudget': comparisons['shared-tail']['emptyVersusSelectedMask256'][-1]}, indent=2))


if __name__ == '__main__':
    main()
